pub struct UnitDef {
    pub id: UnitType,
    pub cost: i32,
    pub trainable: bool,
    /// None for boats whose HP is the passenger's
    pub hp: Option<f64>,
    pub attack: f64,
    pub defence: f64,
    pub movement: i32,
    pub range: i32,
    /// bit mask over Skill
    pub skills: u64,
    /// the skills in data.ts order
    pub skill_list: &'static [Skill],
    pub tech: Option<Tech>,
    pub naval: bool,
    pub ice_movement: Option<i32>,
}

impl UnitDef {
    #[inline]
    pub fn has(&self, s: Skill) -> bool {
        self.skills & (1u64 << (s as u32)) != 0
    }
}

